DO $$
DECLARE
  rec RECORD;
  cur CURSOR FOR SELECT transaction_id, merchant_category, amount, risk_score, is_flagged, customer_tier FROM transaction_approvals ORDER BY transaction_id;
BEGIN
  OPEN cur;
  LOOP
    FETCH cur INTO rec;
    EXIT WHEN NOT FOUND;

    -- Rule 1: gambling and amount > 500
    IF rec.merchant_category = 'gambling' AND rec.amount > 500 THEN
      UPDATE transaction_approvals
      SET risk_score = risk_score + 15
      WHERE transaction_id = rec.transaction_id;
      rec.risk_score := rec.risk_score + 15;
    END IF;

    -- Rule 2: risk_score > 70
    IF rec.risk_score > 70 THEN
      UPDATE transaction_approvals
      SET is_flagged = TRUE
      WHERE transaction_id = rec.transaction_id;
      rec.is_flagged := TRUE;
    END IF;

    -- Rule 3: is_flagged and premium tier
    IF rec.is_flagged = TRUE AND rec.customer_tier = 'premium' THEN
      UPDATE transaction_approvals
      SET risk_score = risk_score - 10
      WHERE transaction_id = rec.transaction_id;
    END IF;
  END LOOP;
  CLOSE cur;
END $$;

SELECT * FROM transaction_approvals ORDER BY transaction_id;
